function config({ spreadsheetId, sheetName, listId }) {
  for (const [k, v] of Object.entries({ spreadsheetId, sheetName, listId }))
    if (typeof v !== "string" || !v.trim() || v.startsWith("YOUR_")) throw Error("Configure " + k);
  return { spreadsheetId, sheetName, listId, range: "'" + sheetName.replace(/'/g, "''") + "'" };
}

const server = "YOUR_MAILCHIMP_SERVER_PREFIX";
if (!/^[a-z]{2}[0-9]{1,3}$/.test(server)) throw Error("Configure the Mailchimp server prefix");
return [
  {
    json: {
      ...config({
        spreadsheetId: "YOUR_SPREADSHEET_ID",
        sheetName: "Signups",
        listId: "YOUR_MAILCHIMP_AUDIENCE_ID",
      }),
      server,
    },
  },
];

function validate({ values }) {
  if (!Array.isArray(values)) throw Error("Invalid sheet response");
  if (!values.length) return { items: [] };
  const h = values[0];
  if (!Array.isArray(h)) throw Error("Invalid header");
  const fields = ["Email Address", "Name", "Submitted On"],
    idx = fields.map((x) => h.indexOf(x));
  if (idx.some((x) => x < 0) || fields.some((x) => h.filter((y) => y === x).length !== 1))
    throw Error("Required headers are missing or duplicated");
  const seen = new Set(),
    items = [];
  for (const row of values.slice(1)) {
    if (!Array.isArray(row) || row.every((x) => x === null || x === undefined || x === ""))
      continue;
    const [email, name, time] = idx.map((i) => row[i]);
    if (
      typeof email !== "string" ||
      !/^\S+@\S+\.\S+$/.test(email.trim()) ||
      typeof name !== "string" ||
      !name.trim() ||
      typeof time !== "string" ||
      !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)$/.test(time) ||
      !Number.isFinite(Date.parse(time))
    )
      throw Error("Each signup requires an email, name and ISO timestamp with time zone");
    const m = time.match(
        /^(\d{4})-(\d\d)-(\d\d)T(\d\d):(\d\d):(\d\d)(?:\.\d+)?(Z|([+-])(\d\d):(\d\d))$/,
      ),
      d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
    if (
      d.getUTCFullYear() !== +m[1] ||
      d.getUTCMonth() !== +m[2] - 1 ||
      d.getUTCDate() !== +m[3] ||
      +m[4] > 23 ||
      +m[5] > 59 ||
      +m[6] > 59 ||
      (m[7] !== "Z" && (+m[9] > 23 || +m[10] > 59))
    )
      throw Error("Invalid signup timestamp");
    const key = email.trim().toLowerCase();
    if (seen.has(key)) throw Error("Duplicate email in the sheet");
    seen.add(key);
    items.push({ email: email.trim(), name: name.trim(), timestamp: new Date(time).toISOString() });
  }
  return { items };
}

return validate({ values: $input.first().json.values ?? [] }).items.map((json, i) => ({
  json,
  pairedItem: { item: 0 },
}));

function confirm({ body, statusCode, bodyEncoding, expected }) {
  if (
    statusCode !== 200 ||
    bodyEncoding ||
    !body ||
    typeof body.id !== "string" ||
    !body.id ||
    typeof body.email_address !== "string" ||
    body.email_address.toLowerCase() !== expected.toLowerCase() ||
    body.status !== "subscribed"
  )
    throw Error("Mailchimp did not confirm the subscriber");
  return { member: body };
}

const x = $input.first().json,
  p = $("Import one signup at a time").item.json;
return [
  {
    json: confirm({ body: x.body, statusCode: x.statusCode, bodyEncoding: null, expected: p.email })
      .member,
  },
];
